<?php
declare(strict_types=1);
namespace BYPCMS\Core;
require_once __DIR__.'/Content.php';
require_once __DIR__.'/Journal.php';

final class Atelier {
    public static function imageSources(string $url): string {
        if(preg_match('#^/themes/atelier/assets/project-[1-4]\.jpg$#D',$url)){
            $base=substr($url,0,-4);$e=[Content::class,'e'];return ' srcset="'.$e(Content::asset($base.'-480.webp')).' 480w, '.$e(Content::asset($base.'-1280.webp')).' 1280w, '.$e(Content::asset($url)).' 1800w" sizes="(max-width:650px) 100vw, (max-width:1000px) 80vw, 1200px"';
        }
        return Content::imageSet($url);
    }
    public static function render(array $pages,array $s,string $path,string $base='',array $options=[]): void {
        $e=[Content::class,'e'];$path=trim($path,'/');$token=$options['snapshot']??'';
        $href=static fn(string $p,array $q=[])=>$base.$p.(($q+($token?['snapshot'=>$token]:[]))?'?'.http_build_query($q+($token?['snapshot'=>$token]:[])):'');
        $services=array_values(array_filter($pages,fn($p)=>$p['kind']==='service'));
        $projects=array_values(array_filter($pages,fn($p)=>$p['kind']==='project'));
        $team=array_values(array_filter($pages,fn($p)=>$p['kind']==='person'));
        $find=static function(string $slug)use($pages){foreach($pages as $p)if(trim($p['slug'],'/')===$slug)return $p;return null;};
        $p=$path!==''?$find($path):null;$mode=$p?'detail':([''=>'home','services'=>'services','projects'=>'projects','team'=>'team','contact'=>'contact','search'=>'search','request-success'=>'success'][$path]??'404');
        $preview=!empty($options['preview']);$status=$mode==='404'?404:200;if($mode==='success'&&empty($options['receipt'])){$status=404;$mode='404';}
        http_response_code($options['http_status']??$status);header('Content-Type: text/html; charset=utf-8');header('X-Content-Type-Options: nosniff');
        header("Content-Security-Policy: default-src 'self'; img-src 'self' https: data:; style-src 'self' 'unsafe-inline'; font-src 'self'; script-src 'self'; frame-ancestors 'self'; base-uri 'none'; form-action 'self'");
        if($preview||$mode==='success'||$base!==''){header('X-Robots-Tag: noindex, nofollow');header('Cache-Control: no-store');}
        $name=$s['site_name']??'Atelier';$title=$p?(($p['seo_title']??'')?:$p['title']):(['home'=>'Архитектура осмысленной жизни','services'=>'Услуги','projects'=>'Избранные проекты','team'=>'Команда','contact'=>'Обсудим вашу задачу','search'=>'Поиск','success'=>'Заявка сохранена','404'=>'Страница не найдена'][$mode]);
        $description=$p?(($p['seo_description']??'')?:$p['excerpt']):($s['tagline']??'Пространства для жизни и работы.');$accent=preg_match('/^#[a-f0-9]{6}$/i',$s['accent']??'')?$s['accent']:'#d9fd75';
        $canonical=Content::url($p['canonical']??'')?:rtrim($s['site_url']??'','/').$base.'/'.($path?$path.'/':'');$cover=$p['cover']??($projects[0]['cover']??'');
        $asset=static fn($p)=>Content::asset('/themes/atelier/'.$p);
        $image=static function(array $p,string $class='',bool $eager=false)use($e){$src=Content::asset(Content::imageUrl($p['cover']??''));return $src?'<img class="'.$class.'" src="'.$e($src).'"'.self::imageSources($p['cover']).' alt="'.$e($p['cover_alt']??$p['title']).'" '.($eager?'fetchpriority="high"':'loading="lazy"').' decoding="async">':'<div class="a-noimage '.$class.'">Изображение не добавлено</div>';};
        $cta=static fn(array $q=[])=>$href('/contact/',$preview?[]:$q);
        $cards=static function(array $items,string $empty='Пока нет опубликованных проектов в этом направлении.')use($e,$href,$image){if(!$items){echo '<p class="a-empty">'.$e($empty).'</p>';return;}foreach($items as $i=>$v){echo '<article class="a-project"><a class="a-picture" href="'.$e($href('/'.$v['slug'].'/')).'">'.$image($v).'<span>Подробнее ↗</span></a><div class="a-project-caption"><a href="'.$e($href('/'.$v['slug'].'/')).'"><h3>'.$e($v['title']).'</h3></a><span>'.$e($v['location']??'').'</span></div><p>'.$e($v['excerpt']).'</p></article>';}};
        ?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $e($title.' — '.$name) ?></title><meta name="description" content="<?= $e($description) ?>"><link rel="canonical" href="<?= $e($canonical) ?>"><meta property="og:title" content="<?= $e($title) ?>"><meta property="og:description" content="<?= $e($description) ?>"><meta property="og:type" content="website"><?php if($cover): ?><meta property="og:image" content="<?= $e(str_starts_with($cover,'/')?rtrim($s['site_url']??'','/').Content::asset($cover):$cover) ?>"><?php endif ?><?php if(!empty($p['noindex'])): ?><meta name="robots" content="noindex,follow"><?php endif ?><link rel="stylesheet" href="<?= $e($asset('atelier.css')) ?>?v=2.2.0"><script src="<?= $e($asset('atelier.js')) ?>?v=2.2.0" defer></script><style>:root{--a-accent:<?= $e($accent) ?>;--a-font:<?= ($s['font']??'')==='system'?'system-ui':'AtelierSans' ?>;--a-heading:<?= ($s['heading_font']??'')==='georgia'?'Georgia,serif':'var(--a-font)' ?>}</style></head>
        <body class="a-site a-view-<?= $e($mode) ?>"><?php if($preview): ?><div class="a-preview-banner">Предпросмотр · изменения ещё не опубликованы <a id="preview-close" href="/manage/">Закрыть ×</a></div><script src="<?= $e(Content::asset('/themes/journal/preview.js')) ?>" defer></script><?php endif ?><a class="a-skip" href="#main">К содержанию</a>
        <header class="a-header"><a class="a-logo" href="<?= $e($href('/')) ?>"><?php if(!empty($s['logo'])): ?><img src="<?= $e(Content::imageUrl($s['logo'])) ?>" alt="<?= $e($name) ?>"><?php else: ?><?= $e($name) ?><span class="a-dot" aria-hidden="true"></span><?php endif ?></a><button class="a-menu-toggle" aria-expanded="false" aria-controls="atelier-nav">Меню <span>☰</span></button><nav id="atelier-nav" aria-label="Основное меню"><a href="<?= $e($href('/projects/')) ?>">Проекты</a><a href="<?= $e($href('/services/')) ?>">Услуги</a><a href="<?= $e($href('/about/')) ?>">О студии</a><?php if($team): ?><a href="<?= $e($href('/team/')) ?>">Команда</a><?php endif ?><a href="<?= $e($href('/search/')) ?>" aria-label="Поиск по сайту">Поиск</a><?= Journal::menu($s['menu']??[]) ?></nav><a class="a-header-contact" href="<?= $e($cta()) ?>">Обсудить проект <span>↗</span></a></header>
        <main id="main">
        <?php if($mode==='home'): $featuredHero=array_values(array_filter($projects,fn($v)=>!empty($v['featured'])));$hero=$featuredHero[0]??$projects[0]??null; ?>
        <section class="a-hero"><div class="a-hero-top"><span>АРХИТЕКТУРА / ИНТЕРЬЕРЫ / СРЕДА</span><span>ОТ ИДЕИ ДО ПРОСТРАНСТВА</span></div><h1><?= $e($s['tagline']??'Пространства для жизни и работы.') ?></h1><div class="a-hero-bottom"><p>Внимание к человеку.<br>Уважение к месту.<br>Точность в каждой детали.</p><a class="a-round" href="<?= $e($href('/projects/')) ?>" aria-label="Смотреть проекты">↘</a></div><?php if($hero): ?><a class="a-hero-image" href="<?= $e($href('/'.$hero['slug'].'/')) ?>"><?= $image($hero,'',true) ?><span><?= $e($hero['title']) ?> <b>СМОТРЕТЬ ПРОЕКТ ↗</b></span></a><?php endif ?></section>
        <section class="a-intro a-wrap"><span class="a-kicker">01 / ФИЛОСОФИЯ</span><div><h2>Не просто красиво.<br>По-настоящему ваше.</h2><p><?= $e($find('about')['excerpt']??'Рассказываем о пространстве через задачи и решения, которые в нём живут.') ?></p><a class="a-text-link" href="<?= $e($href('/about/')) ?>">Познакомиться со студией ↗</a></div></section>
        <section class="a-wrap a-projects-section"><div class="a-section-heading"><h2>Избранные<br>пространства<span> / <?= count($projects) ?></span></h2><a class="a-text-link" href="<?= $e($href('/projects/')) ?>">Все проекты ↗</a></div><div class="a-project-grid"><?php $featured=array_values(array_filter($projects,fn($v)=>!empty($v['featured'])));$cards(array_slice($featured?array_merge($featured,array_filter($projects,fn($v)=>empty($v['featured']))):$projects,0,4)); ?></div></section>
        <section class="a-services-section a-wrap"><div class="a-section-heading"><span class="a-kicker">02 / НАПРАВЛЕНИЯ</span><h2>От первого вопроса<br>до целого решения.</h2></div><?php foreach($services as $i=>$v): ?><a class="a-service-row" href="<?= $e($href('/'.$v['slug'].'/')) ?>"><span><?= sprintf('%02d',$i+1) ?></span><h3><?= $e($v['title']) ?></h3><p><?= $e($v['excerpt']) ?></p><b>↗</b></a><?php endforeach; if(!$services): ?><p>Услуги появятся после публикации в панели.</p><?php endif ?></section>
        <?php if($team): ?><section class="a-wrap a-team"><div class="a-section-heading"><span class="a-kicker">03 / КОМАНДА</span><h2>Люди, которые<br>собирают целое.</h2><a href="<?= $e($href('/team/')) ?>">Познакомиться ↗</a></div><div class="a-project-grid"><?php $cards(array_slice($team,0,4)); ?></div></section><?php endif ?>
        <?php elseif(in_array($mode,['projects','services','team','search'],true)):
            $items=$mode==='services'?$services:($mode==='team'?$team:$projects);$filter=(int)($_GET['service']??0);$q=mb_substr(trim((string)($_GET['q']??'')),0,100);
            if($mode==='projects'&&$filter)$items=array_values(array_filter($items,fn($v)=>(int)($v['parent_id']??0)===$filter));
            if($mode==='search')$items=$q===''?[]:array_values(array_filter($pages,fn($v)=>mb_stripos($v['title'].' '.$v['excerpt'].' '.strip_tags($v['content']??''),$q)!==false));
            $total=count($items);$count=max(1,(int)ceil($total/6));$num=min($count,max(1,(int)($_GET['page']??1)));$items=array_slice($items,($num-1)*6,6); ?>
        <section class="a-wrap a-listing"><span class="a-kicker">ATELIER / <?= $e(['projects'=>'ПРОЕКТЫ','services'=>'УСЛУГИ','team'=>'КОМАНДА','search'=>'ПОИСК'][$mode]) ?></span><h1><?= $e($title) ?></h1>
        <?php if($mode==='projects'): ?><nav class="a-filters" aria-label="Направления проектов"><a <?= !$filter?'aria-current="page"':'' ?> href="<?= $e($href('/projects/')) ?>">Все проекты</a><?php foreach($services as $v): ?><a <?= $filter===$v['id']?'aria-current="page"':'' ?> href="<?= $e($href('/projects/',['service'=>$v['id']])) ?>"><?= $e($v['title']) ?></a><?php endforeach ?></nav><?php endif ?>
        <?php if($mode==='search'): ?><form class="a-search" method="get"><label>Что вы ищете?<input name="q" value="<?= $e($q) ?>" maxlength="100" type="search"></label><?php if($token): ?><input type="hidden" name="snapshot" value="<?= $e($token) ?>"><?php endif ?><button>Найти ↗</button><a href="<?= $e($href('/search/')) ?>">Очистить</a></form><?php endif ?><p class="a-count"><?= $total ?> <?= $mode==='search'?'результатов':'публикаций' ?></p>
        <?php if($mode==='services'): foreach($items as $i=>$v): ?><a class="a-service-row" href="<?= $e($href('/'.$v['slug'].'/')) ?>"><span><?= sprintf('%02d',$i+1) ?></span><h2><?= $e($v['title']) ?></h2><p><?= $e($v['excerpt']) ?></p><b>↗</b></a><?php endforeach; else: ?><div class="a-project-grid"><?php $cards($items,$mode==='search'?($q===''?'Введите запрос, чтобы найти материалы.':'Ничего не найдено. Попробуйте другой запрос.') :($mode==='team'?'Информация о команде появится здесь.':'Пока нет опубликованных проектов в этом направлении.')); ?></div><?php endif ?>
        <?php if(!$items&&$mode==='services'): ?><p class="a-empty">Пока нет опубликованных услуг.</p><?php endif; if($count>1): ?><nav class="a-pagination" aria-label="Страницы"><?php for($i=1;$i<=$count;$i++): ?><a <?= $i===$num?'aria-current="page"':'' ?> href="<?= $e($href('/'.$mode.'/',array_filter(['service'=>$filter,'q'=>$q,'page'=>$i]))) ?>"><?= $i ?></a><?php endfor ?></nav><?php endif ?></section>
        <?php elseif($mode==='detail'): ?>
        <article class="a-detail"><div class="a-wrap"><nav class="a-breadcrumb" aria-label="Хлебные крошки"><a href="<?= $e($href('/')) ?>">Главная</a><span>/</span><a href="<?= $e($href($p['kind']==='service'?'/services/':($p['kind']==='project'?'/projects/':'/about/'))) ?>"><?= $e(['service'=>'Услуги','project'=>'Проекты','person'=>'Команда','page'=>'Студия'][$p['kind']]??'Студия') ?></a></nav><div class="a-detail-heading"><h1><?= $e($p['title']) ?></h1><p><?= $e($p['excerpt']) ?></p></div><?php if($p['kind']==='project'): ?><dl class="a-facts"><?php foreach(['location'=>'Объект','year'=>'Этап / год','client'=>'Клиент']as $key=>$label)if(!empty($p[$key])): ?><div><dt><?= $label ?></dt><dd><?= $e($p[$key]) ?></dd></div><?php endif; foreach($services as $service)if($service['id']===(int)($p['parent_id']??0)): ?><div><dt>Направление</dt><dd><a href="<?= $e($href('/'.$service['slug'].'/')) ?>"><?= $e($service['title']) ?></a></dd></div><?php endif ?><?php foreach($team as $member)if($member['id']===(int)($p['person_id']??0)): ?><div><dt>Команда проекта</dt><dd><a href="<?= $e($href('/'.$member['slug'].'/')) ?>"><?= $e($member['title']) ?></a></dd></div><?php endif ?></dl><?php endif ?></div>
        <?php if(!empty($p['cover'])): ?><figure class="a-detail-cover"><?= $image($p,'',true) ?></figure><?php endif ?><div class="a-body-layout a-wrap"><aside><span class="a-kicker"><?= $e(['project'=>'О ПРОЕКТЕ','service'=>'ОБ УСЛУГЕ','person'=>'УЧАСТНИК КОМАНДЫ','page'=>'О СТУДИИ'][$p['kind']]??'ПОДРОБНОСТИ') ?></span><?php if(!empty($p['price'])): ?><p><?= $e($p['price']) ?></p><?php endif; if(!empty($p['role'])): ?><p><?= $e($p['role']) ?></p><?php endif ?><a class="a-text-link" href="<?= $e($cta($p['kind']==='service'?['service'=>$p['id']]:($p['kind']==='project'?['project'=>$p['id'],'service'=>$p['parent_id']??0]:[]))) ?>">Обсудить похожую задачу ↗</a></aside><div class="a-prose"><?= Content::html($p['content']??'').Content::blocks($p['blocks']??[]) ?></div></div></article>
        <?php if($p['kind']==='service'): $related=array_values(array_filter($projects,fn($v)=>(int)($v['parent_id']??0)===$p['id'])); ?><section class="a-wrap"><div class="a-section-heading"><h2>Воплощение идей</h2><a href="<?= $e($href('/projects/',['service'=>$p['id']])) ?>">Все проекты направления ↗</a></div><div class="a-project-grid"><?php $cards(array_slice($related,0,2)); ?></div></section><?php elseif($p['kind']==='person'): $related=array_values(array_filter($projects,fn($v)=>(int)($v['person_id']??0)===$p['id']));if($related): ?><section class="a-wrap"><div class="a-section-heading"><h2>Проекты участника</h2></div><div class="a-project-grid"><?php $cards($related); ?></div></section><?php endif ?><?php elseif($p['kind']==='project'): $next=array_values(array_filter($projects,fn($v)=>$v['id']!==$p['id']));if($next): ?><section class="a-next a-wrap"><span class="a-kicker">СЛЕДУЮЩИЙ ПРОЕКТ</span><a href="<?= $e($href('/'.$next[0]['slug'].'/')) ?>"><?= $e($next[0]['title']) ?> ↗</a></section><?php endif; endif ?>
        <?php elseif($mode==='contact'): ?><section class="a-contact a-wrap"><div><span class="a-kicker">СЛЕДУЮЩИЙ ШАГ</span><h1>Расскажите,<br>что вы задумали.</h1><p>Достаточно нескольких слов о задаче. Мы обсудим состав проекта и дальнейшие шаги.</p><?php foreach(['email','phone']as $key)if(!empty($s[$key])): ?><a class="a-contact-link" href="<?= $e(($key==='email'?'mailto:':'tel:').preg_replace($key==='phone'?'/[^+0-9]/':'/\s/','',$s[$key])) ?>"><?= $e($s[$key]) ?></a><?php endif ?></div><div><?= $options['form']??'<div class="a-form-notice"><h2>Заявка в установленной CMS</h2><p>В этой публичной демонстрации данные не отправляются. В клиентском Business форма сохраняет заявку в CRM, а сотрудник назначает ответственного и обрабатывает обращение.</p></div>' ?></div></section>
        <?php elseif($mode==='success'): ?><section class="a-wrap a-message"><span class="a-kicker">ЗАЯВКА СОХРАНЕНА</span><h1>Спасибо.<br>Мы получили вашу задачу.</h1><p>Номер обращения: <strong><?= $e($options['receipt']) ?></strong>. Сохраните номер обращения. Ответим по оставленным контактам.</p><a class="a-button" href="<?= $e($href('/projects/')) ?>">Посмотреть проекты ↗</a></section>
        <?php else: ?><section class="a-wrap a-message"><span class="a-kicker">404 / НЕ НАЙДЕНО</span><h1>Здесь пока<br>нет пространства.</h1><p>Страница удалена, не опубликована или адрес изменился.</p><a class="a-button" href="<?= $e($href('/projects/')) ?>">К проектам ↗</a></section><?php endif ?>
        <?php if(!in_array($mode,['contact','success','404'],true)): ?><section class="a-cta a-wrap"><span class="a-kicker">ДАВАЙТЕ НАЧНЁМ С РАЗГОВОРА</span><a href="<?= $e($cta($p&&$p['kind']==='service'?['service'=>$p['id']]:[])) ?>">Есть идея?<br>Обсудим её.<span>↗</span></a></section><?php endif ?></main>
        <footer class="a-footer a-wrap"><a class="a-logo" href="<?= $e($href('/')) ?>"><?= $e($name) ?><span class="a-dot"></span></a><nav aria-label="Меню в подвале"><a href="<?= $e($href('/projects/')) ?>">Проекты</a><a href="<?= $e($href('/services/')) ?>">Услуги</a><a href="<?= $e($href('/contact/')) ?>">Контакты</a><a href="<?= $e($href('/privacy/')) ?>">Обработка данных</a><?= Journal::menu($s['footer_menu']??[]) ?></nav><div class="a-footer-bottom"><span>© <?= gmdate('Y') ?> <?= $e($name) ?></span><?php if(!empty($options['demo'])): ?><span>Иллюстративные проекты. Демонстрационная тема.</span><?php endif ?><span>BYPCMS Business / Atelier</span></div></footer>
        </body></html><?php
    }
}
